class Command(BaseCommand):
    help = 'Seed quizzes for all theory modules'

    def handle(self, *args, **kwargs):
        created_quizzes = 0
        created_questions = 0
        skipped = 0

        for module_id, data in QUIZZES.items():
            try:
                module = TheoryModule.objects.get(id=module_id)
            except TheoryModule.DoesNotExist:
                skipped += 1
                continue

            quiz, quiz_created = Quiz.objects.get_or_create(
                module=module,
                defaults={
                    'title': f'Тест: {module.title}',
                    'description': f'Проверь знания по теме: {module.title}',
                    'pass_score': 70,
                    'is_active': True,
                    'order': module.order,
                }
            )
            if quiz_created:
                created_quizzes += 1

            for i, q in enumerate(data['questions'], start=1):
                question, q_created = Question.objects.get_or_create(
                    quiz=quiz,
                    order=i,
                    defaults={
                        'text': q['text'],
                        'q_type': 'single',
                        'explanation': q.get('exp', ''),
                    }
                )
                if q_created:
                    created_questions += 1

                for j, (choice_text, is_correct) in enumerate(q['choices'], start=1):
                    AnswerChoice.objects.get_or_create(
                        question=question,
                        order=j,
                        defaults={'text': choice_text, 'is_correct': is_correct}
                    )

        total = Quiz.objects.filter(is_active=True, module__isnull=False).count()
        self.stdout.write(
            f'Done: +{created_quizzes} quizzes, +{created_questions} questions. '
            f'Skipped {skipped} missing modules. '
            f'Total active quizzes with module: {total}'
        )
